class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        best = float('inf')
        for x in range(k):
            for y in range(k):
                if x == y:
                    continue
                total = 0
                for i, v in enumerate(nums):
                    t = x if i % 2 == 0 else y
                    d = abs(v % k - t)
                    total += min(d, k - d)
                best = min(best, total)
        return best

