class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        even = [0] * k
        odd = [0] * k
        for i, v in enumerate(nums):
            r = v % k
            tab = even if i % 2 == 0 else odd
            for t in range(k):
                d = abs(r - t)
                tab[t] += min(d, k - d)
        return min(even[x] + odd[y]
                   for x in range(k) for y in range(k) if x != y)

