public:
    long long minOperations(vector<int>& nums, int k) {
        vector<long long> even(k, 0), odd(k, 0);
        for (int i = 0; i < (int)nums.size(); i++) {
            int r = nums[i] % k;
            auto& tab = (i % 2 == 0) ? even : odd;
            for (int t = 0; t < k; t++) {
                int d = abs(r - t);
                tab[t] += min(d, k - d);
            }
        }
        long long best = LLONG_MAX;
        for (int x = 0; x < k; x++)
            for (int y = 0; y < k; y++)
                if (x != y) best = min(best, even[x] + odd[y]);
        return best;
    }
};

