var minOperations = function(nums, k) {
    const even = new Array(k).fill(0), odd = new Array(k).fill(0);
    for (let i = 0; i < nums.length; i++) {
        const r = nums[i] % k;
        const tab = i % 2 === 0 ? even : odd;
        for (let t = 0; t < k; t++) {
            const d = Math.abs(r - t);
            tab[t] += Math.min(d, k - d);
        }
    }
    let best = Infinity;
    for (let x = 0; x < k; x++)
        for (let y = 0; y < k; y++)
            if (x !== y) best = Math.min(best, even[x] + odd[y]);
    return best;
};
